//! term-core's Unicode table and grapheme segmentation (cells design §6.2).
//!
//! [`props`] gives, per scalar, everything the terminal needs to place it:
//! width and the East Asian Ambiguous flag, the Grapheme_Cluster_Break
//! class, and the emoji properties the width rule uses. The table is
//! generated by `crates/term-core/unicode/generate.py` from the Unicode
//! character database of the version `unicode-width` uses, and its widths
//! equal `unicode-width`'s per scalar (tests/unicode.rs), apart from the
//! exceptions listed there.
//!
//! [`Segmenter`] finds grapheme cluster boundaries (UAX #29) one scalar at
//! a time, as text arrives, and works out each cluster's width (§6.3).

mod table;

pub use table::UNICODE_VERSION;

/// Grapheme_Cluster_Break classes (UAX #29).
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
#[repr(u8)]
pub enum Gcb {
    #[default]
    Other = 0,
    Cr,
    Lf,
    Control,
    Extend,
    Zwj,
    RegionalIndicator,
    Prepend,
    SpacingMark,
    L,
    V,
    T,
    Lv,
    Lvt,
}

const GCBS: [Gcb; 16] = [
    Gcb::Other,
    Gcb::Cr,
    Gcb::Lf,
    Gcb::Control,
    Gcb::Extend,
    Gcb::Zwj,
    Gcb::RegionalIndicator,
    Gcb::Prepend,
    Gcb::SpacingMark,
    Gcb::L,
    Gcb::V,
    Gcb::T,
    Gcb::Lv,
    Gcb::Lvt,
    Gcb::Other,
    Gcb::Other,
];

/// Indic_Conjunct_Break values (rule GB9c).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u8)]
pub enum Incb {
    None = 0,
    Linker,
    Consonant,
    Extend,
}

/// One scalar's entry in the table. Bits: 0–1 width (3 = control), 2
/// ambiguous, 3–6 break class, 7 Extended_Pictographic, 8–9
/// Indic_Conjunct_Break, 10 Emoji_Presentation, 11 Emoji_Modifier_Base,
/// 12 Emoji_Modifier, 13 base of an emoji variation sequence.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Props(u16);

const WIDTH_CONTROL: u16 = 3;
const AMBIGUOUS: u16 = 1 << 2;
const EXT_PICT: u16 = 1 << 7;
const EMOJI_PRESENTATION: u16 = 1 << 10;
const MODIFIER_BASE: u16 = 1 << 11;
const MODIFIER: u16 = 1 << 12;
const VS_BASE: u16 = 1 << 13;
/// Break class, Extended_Pictographic and Indic_Conjunct_Break: all zero
/// for a scalar that only GB9b (after Prepend) can join.
const PLAIN_MASK: u16 = 0x3F8;

impl Props {
    /// 0, 1 or 2 cells, ambiguous characters counted as 1. Not meaningful
    /// for controls.
    #[inline]
    pub fn width(self) -> u8 {
        (self.0 & 3) as u8
    }

    /// The width when East Asian Ambiguous characters are `ambiguous` (1 or
    /// 2) cells wide.
    #[inline]
    pub fn width_with(self, ambiguous: u8) -> u8 {
        if self.0 & AMBIGUOUS != 0 { ambiguous } else { self.width() }
    }

    /// Break class Other, not Extended_Pictographic, no Indic conjunct
    /// role: only a Prepend scalar before it can join it (CJK, Cyrillic,
    /// box drawing, printable ASCII…).
    #[inline]
    pub fn is_plain(self) -> bool {
        self.0 & PLAIN_MASK == 0
    }

    /// A C0 or C1 control (general category Cc): never printed.
    #[inline]
    pub fn is_control(self) -> bool {
        self.0 & 3 == WIDTH_CONTROL
    }

    /// East Asian Width Ambiguous (as `unicode-width`'s `width_cjk` counts
    /// it): one cell, or two with `ambiguous_width = 2`.
    #[inline]
    pub fn ambiguous(self) -> bool {
        self.0 & AMBIGUOUS != 0
    }

    #[inline]
    pub fn gcb(self) -> Gcb {
        GCBS[(self.0 >> 3 & 15) as usize]
    }

    #[inline]
    pub fn extended_pictographic(self) -> bool {
        self.0 & EXT_PICT != 0
    }

    #[inline]
    pub fn incb(self) -> Incb {
        match self.0 >> 8 & 3 {
            0 => Incb::None,
            1 => Incb::Linker,
            2 => Incb::Consonant,
            _ => Incb::Extend,
        }
    }

    #[inline]
    pub fn emoji_presentation(self) -> bool {
        self.0 & EMOJI_PRESENTATION != 0
    }

    #[inline]
    pub fn emoji_modifier_base(self) -> bool {
        self.0 & MODIFIER_BASE != 0
    }

    #[inline]
    pub fn emoji_modifier(self) -> bool {
        self.0 & MODIFIER != 0
    }

    /// The base of an emoji variation sequence: VS16 after it asks for
    /// emoji presentation, VS15 for text.
    #[inline]
    pub fn variation_base(self) -> bool {
        self.0 & VS_BASE != 0
    }
}

/// ASCII's entries, so the ASCII paths never touch the big table: controls,
/// CR and LF, printable characters one cell wide, and `#`, `*` and `0`–`9`
/// as variation-sequence (keycap) bases. A test checks it against the table.
static ASCII: [Props; 128] = {
    let control = Props(WIDTH_CONTROL | (Gcb::Control as u16) << 3);
    let mut t = [control; 128];
    t[b'\r' as usize] = Props(WIDTH_CONTROL | (Gcb::Cr as u16) << 3);
    t[b'\n' as usize] = Props(WIDTH_CONTROL | (Gcb::Lf as u16) << 3);
    let mut b = 0x20;
    while b < 0x7F {
        let keycap = b == b'#' || b == b'*' || b.is_ascii_digit();
        t[b as usize] = Props(1 | if keycap { VS_BASE } else { 0 });
        b += 1;
    }
    t
};

/// The table entry for `c`.
#[inline]
pub fn props(c: char) -> Props {
    let c = c as u32;
    if c < 0x80 {
        return ASCII[c as usize];
    }
    table_props(c)
}

#[inline]
fn table_props(c: u32) -> Props {
    let leaf = table::ROOT[(c >> table::SHIFT) as usize] as usize;
    let i = table::LEAVES[leaf][(c & ((1 << table::SHIFT) - 1)) as usize];
    Props(table::PROPS[i as usize])
}

#[doc(hidden)]
pub fn table_props_for_tests(c: char) -> Props {
    table_props(c as u32)
}

/// `#`, `*` or `0`–`9`: a keycap sequence starts with one of these.
#[inline]
fn is_keycap_base(c: char) -> bool {
    matches!(c, '#' | '*' | '0'..='9')
}

/// Where rule GB11 (emoji ZWJ sequences) stands.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
enum EmojiZwj {
    #[default]
    None,
    /// After Extended_Pictographic Extend*.
    Pict,
    /// After Extended_Pictographic Extend* ZWJ: a pictograph joins.
    PictZwj,
}

/// Where rule GB9c (Indic conjuncts) stands. Unicode 18 dropped the
/// consonant before the linker: the rule is now `Linker Extend* ×
/// Consonant` (Indic_Conjunct_Break values).
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
enum IncbState {
    #[default]
    None,
    /// After InCB=Linker InCB=Extend*: an InCB=Consonant joins.
    Linked,
}

/// What emoji sequence the cluster is so far, for its width (§6.3).
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
enum EmojiSeq {
    #[default]
    None,
    /// An emoji presentation, ZWJ or modifier sequence, a flag or a keycap:
    /// two cells.
    Emoji,
    /// A text presentation sequence (base + VS15): one cell.
    Text,
    /// A keycap base and VS16, waiting for U+20E3.
    KeycapVs16,
}

/// Grapheme cluster boundaries one scalar at a time (UAX #29, rules
/// GB3–GB13 with GB9c), and the width of the cluster so far.
///
/// [`Segmenter::push`] says whether a scalar continues the current cluster;
/// [`Segmenter::reset`] starts afresh (start of text).
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Segmenter {
    /// Break class of the cluster's last scalar; `None` at the start.
    prev: Option<Gcb>,
    /// An odd number of regional indicators in a row so far.
    ri_odd: bool,
    emoji_zwj: EmojiZwj,
    incb: IncbState,
    emoji: EmojiSeq,
    /// The cluster's first scalar and whether it is a keycap base.
    first: Props,
    keycap: bool,
    /// Scalars in the cluster so far.
    len: u16,
}

impl Segmenter {
    /// Forget everything: the next scalar starts a cluster. Only `prev` is
    /// cleared (a store or two on every escape sequence); the next push
    /// rewrites the rest.
    #[inline]
    pub fn reset(&mut self) {
        self.prev = None;
    }

    /// Nothing pushed since the start or the last reset.
    #[inline]
    pub fn is_reset(&self) -> bool {
        self.prev.is_none()
    }

    /// The cluster's first scalar.
    #[inline]
    pub fn first(&self) -> Props {
        self.first
    }

    /// Feed one scalar. Returns true if it continues the current cluster,
    /// false if it starts a new one.
    #[inline]
    pub fn push(&mut self, c: char, p: Props) -> bool {
        // Most text (CJK, Cyrillic, box drawing, …): break class Other, no
        // pictograph, no conjunct role. Only a Prepend scalar joins it, and
        // the state after it is known.
        if p.is_plain() && self.prev != Some(Gcb::Prepend) {
            *self = Segmenter::start_plain(c, p);
            return false;
        }
        self.push_rules(c, p)
    }

    /// [`Segmenter::start`] for a scalar with break class Other, no
    /// pictograph and no conjunct role (printable ASCII, say).
    #[inline]
    pub fn start_plain(c: char, p: Props) -> Segmenter {
        Segmenter {
            prev: Some(Gcb::Other),
            first: p,
            keycap: is_keycap_base(c),
            len: 1,
            ..Segmenter::default()
        }
    }

    /// [`Segmenter::push`] for scalars the rules care about.
    #[inline(never)]
    fn push_rules(&mut self, c: char, p: Props) -> bool {
        let joins = match self.prev {
            None => false,
            Some(prev) => !self.breaks(prev, p.gcb(), p),
        };
        if joins {
            self.join(c, p);
        } else {
            *self = Segmenter::start(c, p);
        }
        joins
    }

    /// The state with `c` starting a cluster. Nothing before a boundary
    /// matters after it: the rules' sequences (GB9c, GB11, GB12/13) only
    /// reach back past a scalar that joined.
    #[inline]
    pub fn start(c: char, p: Props) -> Segmenter {
        if p.is_plain() {
            return Segmenter::start_plain(c, p);
        }
        let gcb = p.gcb();
        Segmenter {
            prev: Some(gcb),
            ri_odd: gcb == Gcb::RegionalIndicator,
            emoji_zwj: if p.extended_pictographic() {
                EmojiZwj::Pict
            } else {
                EmojiZwj::None
            },
            incb: if p.incb() == Incb::Linker {
                IncbState::Linked
            } else {
                IncbState::None
            },
            emoji: EmojiSeq::None,
            first: p,
            keycap: is_keycap_base(c),
            len: 1,
        }
    }

    /// `c` joined the cluster: move the rules' state and the emoji sequence on.
    #[inline]
    fn join(&mut self, c: char, p: Props) {
        let gcb = p.gcb();
        let gb11 = self.emoji_zwj == EmojiZwj::PictZwj && p.extended_pictographic();
        let flag = gcb == Gcb::RegionalIndicator;
        self.ri_odd = flag && !(self.ri_odd && self.prev == Some(Gcb::RegionalIndicator));
        self.emoji_zwj = if p.extended_pictographic() {
            EmojiZwj::Pict
        } else {
            match (self.emoji_zwj, gcb) {
                (EmojiZwj::Pict, Gcb::Extend) => EmojiZwj::Pict,
                (EmojiZwj::Pict, Gcb::Zwj) => EmojiZwj::PictZwj,
                _ => EmojiZwj::None,
            }
        };
        self.incb = match (p.incb(), self.incb) {
            (Incb::Linker, _) | (Incb::Extend, IncbState::Linked) => IncbState::Linked,
            _ => IncbState::None,
        };
        self.prev = Some(gcb);

        let second = self.len == 1;
        self.emoji = match (self.emoji, c) {
            (EmojiSeq::None, '\u{FE0F}') if second && self.keycap => EmojiSeq::KeycapVs16,
            (EmojiSeq::None, '\u{FE0F}') if second && self.first.variation_base() => EmojiSeq::Emoji,
            (EmojiSeq::None, '\u{FE0E}') if second && self.first.variation_base() => EmojiSeq::Text,
            (EmojiSeq::None, '\u{20E3}') if second && self.keycap => EmojiSeq::Emoji,
            (EmojiSeq::KeycapVs16, '\u{20E3}') if self.len == 2 => EmojiSeq::Emoji,
            (EmojiSeq::None, _) if second && p.emoji_modifier() && self.first.emoji_modifier_base() => EmojiSeq::Emoji,
            (_, _) if gb11 || flag => EmojiSeq::Emoji,
            (s, _) => s,
        };
        self.len = self.len.saturating_add(1);
    }

    /// Whether the cluster's last scalar is a Prepend one, which anything
    /// but a control joins (rule GB9b). Printable ASCII joins nothing else.
    #[inline]
    pub fn after_prepend(&self) -> bool {
        self.prev == Some(Gcb::Prepend)
    }

    /// Whether there is a boundary between a scalar of class `prev` and the
    /// next one (`next`, with properties `p`).
    #[inline]
    fn breaks(&self, prev: Gcb, next: Gcb, p: Props) -> bool {
        use Gcb::*;
        match (prev, next) {
            (Cr, Lf) => false,                                      // GB3
            (Cr | Lf | Control, _) => true,                         // GB4
            (_, Cr | Lf | Control) => true,                         // GB5
            (L, L | V | Lv | Lvt) => false,                         // GB6
            (Lv | V, V | T) => false,                               // GB7
            (Lvt | T, T) => false,                                  // GB8
            (_, Extend | Zwj | SpacingMark) => false,               // GB9, GB9a
            (Prepend, _) => false,                                  // GB9b
            (RegionalIndicator, RegionalIndicator) => !self.ri_odd, // GB12, GB13
            _ => {
                let gb9c = self.incb == IncbState::Linked && p.incb() == Incb::Consonant;
                let gb11 = prev == Zwj && self.emoji_zwj == EmojiZwj::PictZwj && p.extended_pictographic();
                !(gb9c || gb11)
            }
        }
    }

    /// The cluster's width with mode 2027 on (§6.3): 2 for an emoji
    /// sequence, 1 for a text presentation sequence, otherwise its first
    /// scalar's width (ambiguous characters counted as `ambiguous` cells),
    /// at least 1.
    #[inline]
    pub fn width(&self, ambiguous: u8) -> u8 {
        match self.emoji {
            EmojiSeq::Emoji => 2,
            EmojiSeq::Text => 1,
            EmojiSeq::None | EmojiSeq::KeycapVs16 => self.first.width_with(ambiguous).max(1),
        }
    }
}

/// Split `s` into grapheme clusters with [`Segmenter`].
pub fn graphemes(s: &str) -> impl Iterator<Item = &str> {
    let mut seg = Segmenter::default();
    let mut start = 0;
    let mut chars = s.char_indices();
    std::iter::from_fn(move || {
        loop {
            let Some((i, c)) = chars.next() else {
                let cluster = (start < s.len()).then(|| &s[start..]);
                start = s.len();
                return cluster;
            };
            if !seg.push(c, props(c)) && i > start {
                let cluster = &s[start..i];
                start = i;
                return Some(cluster);
            }
        }
    })
}

/// The width of one grapheme cluster with mode 2027 on (§6.3), ambiguous
/// characters counted as `ambiguous` (1 or 2) cells.
pub fn cluster_width(cluster: &str, ambiguous: u8) -> u8 {
    let mut seg = Segmenter::default();
    for c in cluster.chars() {
        seg.push(c, props(c));
    }
    seg.width(ambiguous)
}
